"""Write C0_ONLY RowLeaf tombstone cells for the RDL-B driver cases.

Standard byte packing only, like make_driver_cells.py: this never imports or
runs the engine and reads no other fixture. A DELETE tombstone
(dev3-row-delete.md#read) is an XRW1 record with flags bit0 (deleted) and
bit1 (undo), payload kind 0 and no body; it is always stamped
`Transaction(T)` and carries its U. The cells are untrusted literal input for
a test-only source, not stored, authenticated or pinned rows. Expected values
(including each U's before value) are literal in the tests.
"""

from pathlib import Path
from struct import pack, pack_into

HERE = Path(__file__).parent
DATABASE = bytes([0x11]) * 16
TIMELINE = 7
EPOCH = 3


def txn_id(local):
    return DATABASE + pack("<QI4xQ", TIMELINE, EPOCH, local)


def txn_ref(local, generation):
    return txn_id(local) + pack("<Q", generation)


def undo_ref(slot):
    # PageRef(file, page_no, incarnation), slot, six zero bytes, generation.
    return pack("<QQQH6xQ", 0x0000_0001_0000_0002, 9, 2, slot, 4)


def tombstone(row, local, mutation, txn, undo):
    header = bytearray(168)
    header[0:4] = b"XRW1"
    pack_into("<HBBQ", header, 4, 1, 3, 0, row)
    header[16] = 2
    header[24:72] = txn_ref(*txn)
    header[72:112] = txn_id(local)
    pack_into("<Q", header, 112, mutation)
    header[120:160] = undo_ref(undo)
    pack_into("<I", header, 160, 0)
    return bytes(header)


def committed(row, value, local, mutation, q):
    body = pack("<IBq", 1, 2, value)  # one Int64 column
    header = bytearray(168)
    header[0:4] = b"XRW1"
    pack_into("<HBBQ", header, 4, 1, 0, 1, row)
    header[16] = 1
    pack_into("<Q", header, 24, q)
    header[72:112] = txn_id(local)
    pack_into("<Q", header, 112, mutation)
    pack_into("<I", header, 160, len(body))
    return bytes(header) + body


def cell(row, data):
    return pack("<HH", 8, len(data)) + row.to_bytes(8, "big") + data


CELLS = {
    "c05": cell(5, committed(5, 50, local=1, mutation=2, q=2)),
    "d15": cell(15, tombstone(15, local=11, mutation=1, txn=(11, 6), undo=4)),
    "d20": cell(20, tombstone(20, local=9, mutation=1, txn=(9, 5), undo=2)),
    "c30": cell(30, committed(30, 300, local=2, mutation=1, q=5)),
}
LEAVES = {
    "leaf_d": "c05 d15 d20 c30",
}

if __name__ == "__main__":
    lines = [
        "# C0_ONLY: independent RowLeaf tombstone cells; not stored, authenticated or pinned rows.",
        "# DB=11x16; timeline=7; epoch=3; one Int64 column; undo file=0x100000002 page=9 inc=2 gen=4.",
        "# c05 c2; d15 tombstone txn11/g6+U4; d20 tombstone txn9/g5+U2; c30 c5.",
        "# Generated by make_delete_cells.py; expected results are literal in driver/delete_tests.rs.",
    ]
    lines += [f"{name}={data.hex()}" for name, data in CELLS.items()]
    lines += [f"{name}={rows}" for name, rows in LEAVES.items()]
    (HERE / "delete-cells.txt").write_text("\n".join(lines) + "\n")
